solution.solution.cpp:
#include <atomic>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <new>
#include <optional>
#include <span>
#include <vector>

class MessageRing
{
public:
    static constexpr std::uint32_t MAGIC{ 0x474E4952 };
    static constexpr std::uint32_t WRAP{ 0xFFFFFFFF };

    static std::size_t bytesNeeded(std::uint32_t capacity) { return sizeof(Header) + capacity; }

    MessageRing(void* memory, std::uint32_t capacity, bool create)
        : header{ static_cast<Header*>(memory) }, data{ static_cast<std::uint8_t*>(memory) + sizeof(Header) }
    {
        if (create)
        {
            header = new (memory) Header{};
            header->capacity = capacity;
            header->head.store(0, std::memory_order_relaxed);
            header->tail.store(0, std::memory_order_relaxed);
            header->magic = MAGIC;
        }
    }

    bool valid() const { return header->magic == MAGIC; }

    bool send(std::span<const std::uint8_t> payload)
    {
        const std::uint32_t cap{ header->capacity };
        if (payload.size() > cap / 2 - 4) return false;
        const std::uint64_t record{ (4 + payload.size() + 7) / 8 * 8 };
        const std::uint64_t head{ header->head.load(std::memory_order_relaxed) };
        const std::uint64_t tail{ header->tail.load(std::memory_order_acquire) };
        const std::uint64_t at{ head % cap };
        const std::uint64_t toEnd{ cap - at };
        const std::uint64_t padding{ record > toEnd ? toEnd : 0 };
        if (cap - (head - tail) < padding + record) return false;
        std::uint64_t pos{ at };
        if (padding)
        {
            std::memcpy(data + pos, &WRAP, 4);
            pos = 0;
        }
        const auto length{ static_cast<std::uint32_t>(payload.size()) };
        std::memcpy(data + pos, &length, 4);
        if (!payload.empty()) std::memcpy(data + pos + 4, payload.data(), payload.size());
        header->head.store(head + padding + record, std::memory_order_release);
        return true;
    }

    std::optional<std::vector<std::uint8_t>> receive()
    {
        const std::uint32_t cap{ header->capacity };
        std::uint64_t tail{ header->tail.load(std::memory_order_relaxed) };
        const std::uint64_t head{ header->head.load(std::memory_order_acquire) };
        if (tail == head) return std::nullopt;
        std::uint32_t length;
        std::memcpy(&length, data + tail % cap, 4);
        if (length == WRAP)
        {
            tail += cap - tail % cap;
            if (tail == head) { header->tail.store(tail, std::memory_order_release); return std::nullopt; }
            std::memcpy(&length, data + tail % cap, 4);
        }
        const std::uint64_t at{ tail % cap };
        std::vector<std::uint8_t> payload(data + at + 4, data + at + 4 + length);
        header->tail.store(tail + (4 + length + 7) / 8 * 8, std::memory_order_release);
        return payload;
    }

    std::uint64_t pending() const
    {
        return header->head.load(std::memory_order_acquire) - header->tail.load(std::memory_order_acquire);
    }

private:
    struct Header
    {
        std::uint32_t magic;
        std::uint32_t capacity;
        alignas(64) std::atomic<std::uint64_t> head;
        alignas(64) std::atomic<std::uint64_t> tail;
    };
    Header* header;
    std::uint8_t* data;
};

unitTests:
#include <string>
#include <thread>
using Bytes = std::vector<std::uint8_t>;
static Bytes text(const std::string& s) { return Bytes(s.begin(), s.end()); }
static std::string str(const Bytes& b) { return std::string(b.begin(), b.end()); }
struct alignas(64) Memory { unsigned char bytes[8192]; };

TEST("send and receive") {
    static Memory m{};
    MessageRing producer{ m.bytes, 256, true };
    MessageRing consumer{ m.bytes, 0, false };
    CHECK(consumer.valid());
    CHECK(!consumer.receive().has_value());
    CHECK(producer.send(text("hello")));
    CHECK(producer.send(text("")));
    CHECK(producer.send(text("a longer message")));
    CHECK_EQ(producer.pending(), 16u + 8u + 24u);
    CHECK_EQ(str(consumer.receive().value_or(Bytes{})), std::string("hello"));
    CHECK(consumer.receive().value_or(Bytes{ 1 }).empty());
    CHECK_EQ(str(consumer.receive().value_or(Bytes{})), std::string("a longer message"));
    CHECK_EQ(consumer.pending(), 0u);
}
TEST("size limits and a full ring") {
    static Memory m{};
    MessageRing r{ m.bytes, 64, true };
    CHECK(!r.send(Bytes(29, 1)));
    CHECK(r.send(Bytes(28, 1)));
    CHECK(r.send(Bytes(20, 2)));
    CHECK_EQ(r.pending(), 56u);
    CHECK(!r.send(Bytes(5, 3)));
    CHECK(r.receive().has_value());
    CHECK(r.send(Bytes(5, 3)));
    CHECK_EQ(r.pending(), 24u + 8u + 16u);
}
TEST("wrapping with a marker") {
    static Memory m{};
    MessageRing r{ m.bytes, 64, true };
    CHECK(r.send(Bytes(20, 1)));       // 24 bytes at 0
    CHECK(r.send(Bytes(20, 2)));       // 24 bytes at 24
    CHECK(r.receive().has_value());
    CHECK(r.receive().has_value());
    CHECK(r.send(Bytes(20, 3)));       // 16 bytes left before the end: marker, then at 0
    CHECK_EQ(r.pending(), 16u + 24u);
    const auto got{ r.receive() };
    CHECK(got.has_value());
    if (got) { CHECK_EQ(got->size(), 20u); CHECK_EQ((*got)[0], 3); }
    CHECK_EQ(r.pending(), 0u);
    MessageRing again{ m.bytes, 0, false };
    CHECK(again.send(Bytes(4, 9)));
    CHECK_EQ(again.receive().value_or(Bytes{})[0], 9);
}
TEST("thousands of messages across threads") {
    static Memory m{};
    MessageRing producer{ m.bytes, 1024, true };
    MessageRing consumer{ m.bytes, 0, false };
    constexpr int N{ 20000 };
    std::thread t{ [&] {
        for (int i{ 0 }; i < N; ++i)
        {
            const std::string s{ std::to_string(i) + std::string(static_cast<std::size_t>(i % 37), '.') };
            while (!producer.send(text(s))) std::this_thread::yield();
        }
    } };
    bool ok{ true };
    for (int i{ 0 }; i < N;)
    {
        if (const auto msg{ consumer.receive() })
        {
            if (str(*msg) != std::to_string(i) + std::string(static_cast<std::size_t>(i % 37), '.')) ok = false;
            ++i;
        }
        else std::this_thread::yield();
    }
    t.join();
    CHECK(ok);
}

